package org.humanjourney.core.geography.map;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import org.humanjourney.core.geography.*;
import org.humanjourney.core.geography.map.client.*;
import org.humanjourney.core.npc.context.*;
public class GeographyV2ProtocolTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;
 @BeforeAll static void bootstrap(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();}
 @AfterAll static void close(){loader.close();}
 static MapArea maximum(){var geo=GeographyV2Test.parse(GeographyV2Test.resource(2,"large",true,GeographyV2Test.geometry(128)));return new MapProjection.Factory(geo,"era_0").project(new DiscoveryLedger.Snapshot(Set.of(),Set.of("large"),1)).areas().values().iterator().next();}
 static MapPackets.Frame wire(MapPackets.Frame f){var b=MapProtocolTest.buffer();try{MapPackets.CODEC.encode(b,f);assertTrue(b.readableBytes()<=48*1024);var copy=MapPackets.CODEC.decode(b);assertEquals(f,copy);return copy;}finally{b.release();}}
 @Test void maximumAreaFragmentsAndPublishesAtomicallyOutOfOrder(){var area=maximum();var parts=MapGeometryTest.full(2,List.of(area));assertEquals(5,parts.size());var client=new ClientMapState();MapGeometryTest.apply(client,MapGeometryTest.full(1,List.of(MapGeometryTest.area(MapArea.Kind.LOCAL,"old",0,"",0,20))));for(int i=parts.size()-1;i>=0;i--){client.accept(wire(parts.get(i)));if(i>0)assertEquals(Set.of(new MapArea.Key(MapArea.Kind.LOCAL,"old")),client.snapshot().areas().keySet());}assertEquals(area,client.snapshot().areas().get(area.key()));assertEquals(127,client.snapshot().index().hover(GeographyV2Test.DIM,127*300,0).localComponent());}
 @Test void largeTransferInterruptionStaleAndDuplicateFragmentsDoNotRerollVisibleState(){var parts=MapGeometryTest.full(2,List.of(maximum()));var client=new ClientMapState();var old=MapGeometryTest.area(MapArea.Kind.LOCAL,"old",0,"",0,20);MapGeometryTest.apply(client,MapGeometryTest.full(1,List.of(old)));client.accept(parts.getFirst());client.accept(parts.getFirst());assertFalse(client.needsResync());assertEquals(old,client.snapshot().areas().get(old.key()));MapGeometryTest.apply(client,MapGeometryTest.full(3,List.of()));parts.forEach(client::accept);assertEquals(0,client.snapshot().areas().size());}
 @Test void fragmentKeyMismatchAndMissingPiecesKeepLastValid(){var parts=MapGeometryTest.full(2,List.of(maximum()));var fragments=parts.stream().flatMap(f->f.fragments().stream()).toList();assertThrows(RuntimeException.class,()->MapPackets.assemble(fragments.subList(1,fragments.size())));var broken=new ArrayList<MapPackets.Fragment>(fragments);var f=broken.getFirst();broken.set(0,new MapPackets.Fragment(new MapArea.Key(MapArea.Kind.MACRO,"wrong"),f.index(),f.count(),f.length(),f.data()));assertThrows(RuntimeException.class,()->MapPackets.assemble(broken));}
 @Test void discoveredOnlyProjectionAndWireDoNotLeakHiddenV2Geometry(){var geo=GeographyV2Test.parse(GeographyV2Test.resource(2,"known",true,GeographyV2Test.geometry(1)),GeographyV2Test.resource(2,"secret_hidden",true,GeographyV2Test.geometry(128)));var projection=new MapProjection.Factory(geo,"era_0").project(new DiscoveryLedger.Snapshot(Set.of(),Set.of("known"),1));assertEquals(1,projection.areas().size());for(var f:MapGeometryTest.full(1,projection.areas().values())){var b=MapProtocolTest.buffer();try{MapPackets.CODEC.encode(b,f);assertFalse(b.toString(0,b.writerIndex(),java.nio.charset.StandardCharsets.UTF_8).contains("secret_hidden"));}finally{b.release();}}}
 @Test void holeAwareHoverAndRenderingUseSeparateRingsAndVisibleComponents(){var geo=GeographyV2Test.parse(GeographyV2Test.resource(2,"holes",true,GeographyV2Test.geometry(1)),GeographyV2Test.resource(2,"parts",false,GeographyV2Test.geometry(128)));var projected=new MapProjection.Factory(geo,"era_0").project(new DiscoveryLedger.Snapshot(Set.of("parts"),Set.of("holes"),1));var client=new ClientMapState();for(var f:MapGeometryTest.full(1,projected.areas().values()))client.accept(wire(f));var index=client.snapshot().index();assertNull(index.hover(GeographyV2Test.DIM,0,0).localArea());assertNotNull(index.hover(GeographyV2Test.DIM,50,0).localArea());var box=new MapArea.Bounds(299,-10,301,10);assertEquals(1,index.queryParts(GeographyV2Test.DIM,MapArea.Kind.MACRO,box).size());var layers=BoundaryPresentation.plan(index,GeographyV2Test.DIM,box,BoundaryMode.ALL,null);assertEquals(1,layers.size());assertEquals(1,layers.getFirst().component());var selected=BoundaryPresentation.plan(index,GeographyV2Test.DIM,box,BoundaryMode.HOVER,index.hover(GeographyV2Test.DIM,300,0));assertEquals(1,selected.size());assertEquals(1,selected.getFirst().component());var hole=projected.areas().get(new MapArea.Key(MapArea.Kind.LOCAL,"holes"));assertEquals(2,hole.shape().parts().getFirst().rings().size());}
 @Test void allOffAndLocalModesRemainIsolatedFromFeatureModes(){assertEquals(4,BoundaryMode.values().length);assertEquals(3,org.humanjourney.core.mapfeature.client.FeatureMode.values().length);var client=new ClientMapState();MapGeometryTest.apply(client,MapGeometryTest.full(1,List.of(maximum())));assertTrue(BoundaryPresentation.plan(client.snapshot().index(),GeographyV2Test.DIM,new MapArea.Bounds(-200,-200,200,200),BoundaryMode.OFF,null).isEmpty());assertEquals(16*1024,MapPackets.CHUNK_BYTES);assertEquals(288*1024,MapPackets.MAX_AREA_BYTES);assertEquals(8192,MapPackets.MAX_PARTS);assertEquals(24*1024*1024,MapPackets.MAX_TRANSFER_BYTES);}
 @Test void roleRevocationReconnectAndResyncStillWorkWithFragments(){var client=new ClientMapState();var frames=MapGeometryTest.full(1,List.of(maximum()));client.accept(frames.getFirst());client.role(false);frames.forEach(client::accept);assertEquals(0,client.snapshot().count(MapArea.Kind.LOCAL));client.role(true);assertTrue(client.needsResync());client.clear();frames.forEach(client::accept);assertEquals(1,client.snapshot().count(MapArea.Kind.LOCAL));}
 @Test void occupiedRightEdgeDoesNotHideThePair(){var occupied=new BoundaryControlLayout.Rect(875,0,125,600);var pair=BoundaryControlLayout.placePair(1000,600,List.of(occupied)).orElseThrow();assertEquals(691,pair.getFirst().x());assertEquals(64,pair.getFirst().y());for(var r:pair)assertFalse(r.overlaps(occupied));}
}
